<?php
namespace App\Http\Controllers;
use App\Models\FuelPrice; use App\Models\FuelType; use App\Models\Person; use App\Models\User; use App\Models\Vehicle; use App\Services\MasterDataAuditService; use Illuminate\Database\Eloquent\Model; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Gate; use Illuminate\Validation\Rule; use Illuminate\View\View;
class MasterDataController extends Controller
{
 public function index(Request $request,?string $resource=null): View {$this->actor($request);if(!$resource)return view('master-data.index',['resource'=>null,'config'=>null,'records'=>null,'user'=>$request->attributes->get('fleet.user'),'guard'=>$request->attributes->get('fleet.guard')]);$config=$this->config($resource);$model=$config['model'];$query=$model::query();$vehicleStatus=$this->vehicleStatus($request);if($resource==='veiculos'&&$vehicleStatus!=='all')$query->where('status',$vehicleStatus);if($term=trim((string)$request->query('q')))foreach($config['search'] as $column)$query->orWhere($column,'like',"%{$term}%");if(!empty($config['with']))$query->with($config['with']);$records=$query->orderByDesc($config['order'])->paginate(15)->withQueryString();return view('master-data.index',compact('resource','config','records','vehicleStatus')+['user'=>$request->attributes->get('fleet.user'),'guard'=>$request->attributes->get('fleet.guard')]);}
 public function create(Request $request,string $resource): View {$this->actor($request);$config=$this->config($resource);return view('master-data.form',compact('resource','config')+['record'=>null,'user'=>$request->attributes->get('fleet.user'),'guard'=>$request->attributes->get('fleet.guard')]);}
 public function store(Request $request,string $resource,MasterDataAuditService $audit): RedirectResponse {$actor=$this->actor($request);$config=$this->config($resource);$data=$this->prepare($resource,$request->validate($this->rules($resource)));$data=$this->applyMaintenanceMode($resource,$data,$request);if($resource==='precos'){$data['created_by_user_id']=$actor->id;$data['source']='manual';}$record=($config['model'])::create($data);$audit->record($actor,"master_data.{$resource}.created",$record,[],$record->getAttributes(),$request);return redirect()->route('master-data.list',['resource'=>$resource])->with('status',"{$config['singular']} cadastrado com sucesso.");}
 public function edit(Request $request,string $resource,int $record): View {$this->actor($request);$config=$this->config($resource);$record=($config['model'])::findOrFail($record);return view('master-data.form',compact('resource','config','record')+['user'=>$request->attributes->get('fleet.user'),'guard'=>$request->attributes->get('fleet.guard')]);}
 public function update(Request $request,string $resource,int $record,MasterDataAuditService $audit): RedirectResponse {$actor=$this->actor($request);$config=$this->config($resource);/** @var Model $record */$record=($config['model'])::findOrFail($record);$data=$this->prepare($resource,$request->validate($this->rules($resource,$record->id)));$data=$this->applyMaintenanceMode($resource,$data,$request,$record);if($resource==='veiculos'&&$data['current_odometer']<$record->current_odometer)return back()->withErrors(['current_odometer'=>'O hodômetro não pode ser reduzido.'])->withInput();if($resource==='precos')return back()->withErrors(['effective_at'=>'O histórico de preço é somente inclusivo; registre uma nova vigência para corrigir valores.']);$before=$record->getOriginal();$record->update($data);$audit->record($actor,"master_data.{$resource}.updated",$record,$before,$record->fresh()->getAttributes(),$request);return redirect()->route('master-data.list',['resource'=>$resource])->with('status',"{$config['singular']} atualizado com sucesso.");}
 private function vehicleStatus(Request $request): string {$value=(string)$request->query('vehicle_status','active');return in_array($value,['active','maintenance','inactive','all'],true)?$value:'active';} private function actor(Request $request): User {$actor=$request->attributes->get('fleet.user');Gate::forUser($actor)->authorize('manage-master-data');return $actor;}
 private function config(string $resource): array {$fuelOptions=fn()=>FuelType::query()->where('active',true)->orderBy('name')->pluck('name','id')->all();$allFuelOptions=fn()=>FuelType::query()->orderBy('name')->pluck('name','id')->all();return match($resource){'pessoas'=>['model'=>Person::class,'title'=>'Pessoas vinculadas à frota','singular'=>'Pessoa','order'=>'full_name','search'=>['full_name','document','email','sector'],'fields'=>['full_name'=>['Nome completo','text'],'role'=>['Função','select',['driver'=>'Motorista','council_member'=>'Vereador','staff'=>'Servidor','administrator'=>'Administrador']],'sector'=>['Setor','text'],'document'=>['Documento','text'],'phone'=>['Telefone','text'],'email'=>['E-mail','email'],'active'=>['Situação','select',['1'=>'Ativa','0'=>'Inativa']]],'columns'=>['full_name'=>'Nome','role'=>'Função','sector'=>'Setor','phone'=>'Telefone','active'=>'Situação']], 'combustiveis'=>['model'=>FuelType::class,'title'=>'Tipos de combustível','singular'=>'Combustível','order'=>'name','search'=>['name','abbreviation'],'fields'=>['name'=>['Nome','text'],'abbreviation'=>['Sigla','text'],'active'=>['Situação','select',['1'=>'Ativo','0'=>'Inativo']]],'columns'=>['name'=>'Nome','abbreviation'=>'Sigla','active'=>'Situação']], 'precos'=>['model'=>FuelPrice::class,'title'=>'Histórico de preços de referência','singular'=>'Preço de referência','order'=>'effective_at','search'=>['source','legacy_codigo'],'with'=>['fuelType'],'fields'=>['fuel_type_id'=>['Combustível','select',$allFuelOptions],'effective_at'=>['Início da vigência','datetime-local'],'valor_bruto'=>['Preço bruto (R$)','number'],'desconto'=>['Desconto (R$)','number']],'columns'=>['fuelType.name'=>'Combustível','effective_at'=>'Vigência','valor_bruto'=>'Bruto','desconto'=>'Desconto','valorcomb'=>'Preço de referência']], 'veiculos'=>['model'=>Vehicle::class,'title'=>'Veículos da frota','singular'=>'Veículo','order'=>'plate','search'=>['plate','model','brand'],'with'=>['fuelType','activeResponsibilities.person'],'fields'=>['plate'=>['Placa','text'],'model'=>['Modelo','text'],'brand'=>['Marca','text'],'manufacture_year'=>['Ano de fabricação','number'],'fuel_type_id'=>['Combustível','select',$fuelOptions],'current_odometer'=>['Hodômetro atual (km)','number'],'status'=>['Situação cadastral','select',['active'=>'Ativo','inactive'=>'Inativo']],'maintenance_mode'=>['Em manutenção','checkbox'],'maintenance_interval_km'=>['Intervalo de manutenção (km)','number'],'maintenance_interval_days'=>['Intervalo de manutenção (dias)','number']],'columns'=>['plate'=>'Placa','model'=>'Modelo','fuelType.name'=>'Combustível','current_odometer'=>'Hodômetro','status'=>'Situação']],default=>abort(404)};}
 private function rules(string $resource,?int $id=null): array {return match($resource){'pessoas'=>['full_name'=>['required','string','max:180'],'role'=>['required',Rule::in(['driver','council_member','staff','administrator'])],'sector'=>['nullable','string','max:120'],'document'=>['nullable','string','max:32'],'phone'=>['nullable','string','max:32'],'email'=>['nullable','email','max:320'],'active'=>['required','boolean']],'combustiveis'=>['name'=>['required','string','max:80',Rule::unique('fuel_types','name')->ignore($id)],'abbreviation'=>['required','string','max:12'],'active'=>['required','boolean']],'precos'=>['fuel_type_id'=>['required','exists:fuel_types,id'],'effective_at'=>['required','date'],'valor_bruto'=>['required','numeric','min:0'],'desconto'=>['nullable','numeric','min:0']],'veiculos'=>['plate'=>['required','regex:/^[A-Za-z0-9-]{5,10}$/',Rule::unique('vehicles','plate')->ignore($id)],'model'=>['required','string','max:120'],'brand'=>['nullable','string','max:80'],'manufacture_year'=>['nullable','integer','between:1900,'.(now()->year+1)],'fuel_type_id'=>['nullable','exists:fuel_types,id'],'current_odometer'=>['required','integer','min:0'],'status'=>['required',Rule::in(['active','inactive'])],'maintenance_mode'=>['nullable','boolean'],'maintenance_interval_km'=>['required','integer','min:1'],'maintenance_interval_days'=>['required','integer','min:1']],default=>abort(404)};}
 private function prepare(string $resource,array $data): array {foreach(['document','phone','email','brand','fuel_type_id','manufacture_year','sector'] as $field)if(($data[$field]??null)==='')$data[$field]=null;if(isset($data['abbreviation']))$data['abbreviation']=strtoupper(trim($data['abbreviation']));if(isset($data['plate']))$data['plate']=strtoupper(preg_replace('/[^A-Za-z0-9]/','',$data['plate']));if($resource==='precos'){$data['desconto']=$data['desconto']??0;$data['valorcomb']=number_format((float)$data['valor_bruto']-(float)$data['desconto'],3,'.','');if((float)$data['valorcomb']<0)abort(422,'O desconto não pode exceder o preço bruto.');}return $data;}
 private function applyMaintenanceMode(string $resource,array $data,Request $request,?Model $record=null): array {if($resource!=='veiculos')return $data;$maintenance=$request->boolean('maintenance_mode');unset($data['maintenance_mode']);if($maintenance)$data['status']='maintenance';elseif($record?->status==='maintenance'&&($data['status']??null)==='maintenance')$data['status']='active';return $data;}
}
